            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"150\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"220\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">FACT OR FICTION?</text><text x=\"550\" y=\"270\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">How does Roark relate to</text><text x=\"550\" y=\"305\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">the architects of his era?</text><circle cx=\"300\" cy=\"560\" r=\"110\" fill=\"rgba(16,185,129,0.3)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"300\" y=\"568\" text-anchor=\"middle\" fill=\"#fff\" font-weight=\"bold\" font-size=\"24\">ROARK</text><circle cx=\"800\" cy=\"560\" r=\"110\" fill=\"rgba(245,158,11,0.3)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"800\" y=\"568\" text-anchor=\"middle\" fill=\"#fff\" font-weight=\"bold\" font-size=\"24\">WRIGHT</text><line x1=\"410\" y1=\"560\" x2=\"690\" y2=\"560\" stroke=\"#ffd700\" stroke-width=\"2\" stroke-dasharray=\"6\" opacity=\"0.5\"/></svg>",
            "caption": "Test your understanding of Roark's real-world inspirations."
