            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">RECAP DASHBOARD</text><text x=\"550\" y=\"100\" text-anchor=\"middle\" fill=\"#888\" font-size=\"23\">The course in three blocks</text><rect x=\"60\" y=\"160\" width=\"980\" height=\"220\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"215\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">ORIGINS -- L1</text><text x=\"550\" y=\"265\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">1935-43 writing, rejections, Bobbs-Merrill 1943</text><text x=\"550\" y=\"310\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Word-of-mouth bestseller by about 1945</text><rect x=\"60\" y=\"410\" width=\"980\" height=\"220\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"465\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">CHARACTERS -- L2 to L6</text><text x=\"550\" y=\"515\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Roark, Keating, Toohey, Wynand, Dominique</text><text x=\"550\" y=\"560\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Creator, second-hander, power-seeker</text><rect x=\"60\" y=\"660\" width=\"980\" height=\"220\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"715\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"24\">IDEAS AND AFTERLIFE -- L7 to L11</text><text x=\"550\" y=\"765\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Architecture, trial, style, film</text><text x=\"550\" y=\"810\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">Critics and defenders</text></svg>",
